import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const timelines = [];
  let disposed = false;

  root.userData.handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const cardWidth = 2.8;
  const cardHeight = 1.75;

  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });

  const cardUv = uv();
  const lower = vec3(surface);
  const upper = vec3(ink);
  const engineeredGradient = mix(
    lower,
    upper,
    smoothstep(0.0, 1.0, cardUv.y)
  );

  cardMaterial.colorNode = engineeredGradient;

  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = -0.02;
  root.add(card);

  ownedGeometries.push(cardGeometry);
  ownedMaterials.push(cardMaterial);

  const accentGeometry = new PlaneGeometry(0.08, 1.12, 1, 1);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: false
  });
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-1.16, -0.02, 0.045);
  root.add(accentBar);

  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const imageGeometry = new PlaneGeometry(1.35, 0.84, 1, 1);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.22,
    depthWrite: false
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.position.set(0.47, -0.08, 0.025);
  image.renderOrder = 1;
  root.add(image);

  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      ownedTextures.push(texture);
      if (ctx.THREE.SRGBColorSpace) texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? visualSpec.textContent ?? [];
  let textOffset = 0.34;

  for (const item of items) {
    const content = String(item.text ?? '');
    const isHeadline = item.role === 'headline';
    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? (isHeadline ? 39 : 13),
      color: paper,
      align: 'left',
      letterSpacingPx: isHeadline ? 0 : 1
    });

    textObject.position.set(-0.98, textOffset, 0.08);
    textObject.renderOrder = 2;
    root.add(textObject);

    textOffset -= isHeadline ? 0.28 : 0.16;
  }

  const settleTimeline = gsap.timeline({ paused: true });
  settleTimeline.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  settleTimeline.progress(1);
  timelines.push(settleTimeline);

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    root.userData.handlers = {};
  };

  return root;
}
